import theme from '../theme.js';
import t from '../i18n/index.js';

export function OrderList({ orders }) {
  return (
    <section>
      <h2>Order list</h2>
      {orders.length === 0 ? (
        <p style={{ padding: theme.spacing * 3, textAlign: 'center' }}>
          {t('order.empty')}
        </p>
      ) : (
        <ul>
          {orders.map((o) => (
            <li key={o.id}>{o.order_no} — {o.total}</li>
          ))}
        </ul>
      )}
    </section>
  );
}

